import path from 'node:path';
export function loadConfig(overrides={}) {
  const config = {
    port: Number(process.env.PORT ?? 4100),
    dataDir: path.resolve(process.env.CREW_DATA_DIR ?? './data'),
    secret: process.env.CREW_SECRET ?? 'local-development-change-this-secret',
    maxUploadBytes: Number(process.env.CREW_MAX_UPLOAD_BYTES ?? 25*1024*1024),
    baseUrl: process.env.CREW_BASE_URL ?? 'http://localhost:4100',
    sessionDays: 14,
    ...overrides
  };
  if (!Number.isInteger(config.port) || config.port < 0 || config.port > 65535) throw new Error('Invalid PORT');
  if (!Number.isSafeInteger(config.maxUploadBytes) || config.maxUploadBytes < 1) throw new Error('Invalid CREW_MAX_UPLOAD_BYTES');
  if(typeof config.secret!=='string'||!config.secret.length)throw new Error('Invalid CREW_SECRET');
  if(typeof config.baseUrl!=='string')throw new Error('Invalid CREW_BASE_URL');
  const base=new URL(config.baseUrl);
  if(!['http:','https:'].includes(base.protocol))throw new Error('Invalid CREW_BASE_URL');
  return config;
}

export function up(db) {
  db.exec(`CREATE TABLE api_tokens (
    id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    name TEXT NOT NULL,token_hash TEXT NOT NULL UNIQUE,scopes_json TEXT NOT NULL,
    created_at TEXT NOT NULL,expires_at TEXT,revoked_at TEXT,last_used_at TEXT
  );
  CREATE INDEX api_tokens_user ON api_tokens(user_id,created_at,id);
  CREATE TABLE security_audit (
    id TEXT PRIMARY KEY,actor_id TEXT REFERENCES users(id) ON DELETE SET NULL,
    org_id TEXT,project_id TEXT,entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,
    action TEXT NOT NULL,before_json TEXT,after_json TEXT,time TEXT NOT NULL
  );
  CREATE INDEX audit_org_time ON security_audit(org_id,time,id);
  CREATE INDEX audit_actor_time ON security_audit(actor_id,time,id);
  CREATE INDEX audit_entity ON security_audit(entity_type,entity_id,time);`);
}

import {choice,date,text,PERMISSIONS} from '@crew/shared';
const securityTypes=['user','session','api_token','invitation','organization','team'];
const safeFields=new Set(['id','orgId','projectId','userId','name','email','role','projectIds','scopes',
  'createdBy','createdAt','updatedAt','expiresAt','acceptedAt','acceptedBy','revokedAt','state',
  'current','count','otherSessionsRevoked','allSessionsRevoked','apiTokensRevoked']);
export function sanitizeAudit(value) {
  if(value===null||value===undefined)return null;
  if(typeof value!=='object'||Array.isArray(value))return null;
  const output={};
  for(const [key,item] of Object.entries(value)) {
    if(!safeFields.has(key))continue;
    if(['projectIds','scopes'].includes(key)) {
      if(Array.isArray(item))output[key]=item.filter(x=>typeof x==='string').slice(0,200).map(x=>x.slice(0,150));
    }else if(item===null||typeof item==='boolean'||typeof item==='number')output[key]=item;
    else if(typeof item==='string')output[key]=item.slice(0,500);
  }
  return output;
}
export const publicAudit=row=>({id:row.id,actorId:row.actor_id,orgId:row.org_id,projectId:row.project_id,
  entityType:row.entity_type,entityId:row.entity_id,action:row.action,
  before:row.before_json?JSON.parse(row.before_json):null,after:row.after_json?JSON.parse(row.after_json):null,time:row.time});
export function auditFilters(query) {
  const filters={};
  if(query.actorId)filters.actorId=text(query.actorId,'actorId',{max:150});
  if(query.entityId)filters.entityId=text(query.entityId,'entityId',{max:150});
  if(query.projectId)filters.projectId=text(query.projectId,'projectId',{max:150});
  if(query.entityType)filters.entityType=choice(query.entityType,'entityType',[...securityTypes,'project']);
  if(query.action)filters.action=text(query.action,'action',{max:100});
  if(query.from)filters.from=date(query.from,'from');
  if(query.to)filters.to=date(query.to,'to');
  if(filters.from&&filters.to&&filters.from>filters.to)throw Object.assign(new Error('From must not be after To'),{code:'VALIDATION',status:422,details:{from:'Choose a date before To'}});
  return filters;
}
export function registerAudit(ctx) {
  const {db,app,requireAuth,permissions:p}=ctx;
  const insert=db.prepare('INSERT INTO security_audit VALUES (?,?,?,?,?,?,?,?,?,?)');
  const release=ctx.bus.subscribe(event=>{
    const selected=securityTypes.includes(event.entityType)||(event.entityType==='project'&&['guest_added','guest_removed'].includes(event.action));
    if(!selected)return;
    const before=sanitizeAudit(event.before),after=sanitizeAudit(event.after);
    insert.run(event.id,event.actorId??null,event.orgId??null,event.projectId??null,event.entityType,event.entityId,event.action,
      before===null?null:JSON.stringify(before),after===null?null:JSON.stringify(after),event.time);
  });
  (ctx.cleanups??=[]).push(release);
  function list(req,where,values) {
    const filters=auditFilters(req.query);
    const names={actorId:'actor_id',entityId:'entity_id',projectId:'project_id',entityType:'entity_type',action:'action'};
    for(const [key,value] of Object.entries(filters)) {
      where.push(key==='from'?'time>=?':key==='to'?'time<=?':names[key]+'=?');values.push(value);
    }
    const rows=db.prepare('SELECT * FROM security_audit WHERE '+where.join(' AND ')+' ORDER BY time DESC,id').all(...values);
    return ctx.paginate(rows.map(publicAudit),req.query);
  }
  app.get('/api/v1/orgs/:orgId/audit',requireAuth,(req,res)=>{
    p.assertOrg(req,req.params.orgId,'audit:read');
    if(req.query.projectId){const project=p.assertProject(req,req.query.projectId,'project:read');if(project.org_id!==req.params.orgId)return res.status(422).json({error:{code:'VALIDATION',message:'Project belongs to another organization',details:{projectId:'Choose a project in this organization'}}});}
    res.json(list(req,['org_id=?'],[req.params.orgId]));
  });
  app.get('/api/v1/me/audit',requireAuth,(req,res)=>{
    p.assertSelf(req);res.json(list(req,['org_id IS NULL','(actor_id=? OR entity_id=?)'],[req.user.id,req.user.id]));
  });
}

import {registerTokens} from './tokens.js';
import {registerAudit} from './audit.js';
import {registerInvitations} from './invitations.js';
import {registerAccount} from './account.js';
import {registerOutbox} from './outbox-routes.js';
import {createPermissions} from '../../http/middleware/permissions.js';
import {registerOrganizations} from './orgs.js';
import {registerTeams} from './teams.js';
import {enqueueOutbox} from './outbox.js';
export function registerRoutes(ctx) {
  ctx.permissions=createPermissions(ctx);
  ctx.enqueueOutbox=input=>enqueueOutbox(ctx,input);
  registerAudit(ctx);
  registerTokens(ctx);
  registerOrganizations(ctx);
  registerTeams(ctx);
  registerInvitations(ctx);
  registerAccount(ctx);
  registerOutbox(ctx);
}

import {AppError,tokenInput,PERMISSIONS,scopeAllows,choice} from '@crew/shared';
import {hashToken,publicUser} from '../../http/middleware/auth.js';
import {issueCredential,verifyCredential} from '../auth/credentials.js';
import {securityEvent} from './security-events.js';
export function tokenState(row,time=new Date().toISOString()) {
  return row.revoked_at?'revoked':row.expires_at&&row.expires_at<=time?'expired':'active';
}
export const publicToken=row=>({id:row.id,name:row.name,scopes:JSON.parse(row.scopes_json),
  createdAt:row.created_at,expiresAt:row.expires_at,revokedAt:row.revoked_at,
  lastUsedAt:row.last_used_at,state:tokenState(row)});
export function registerTokens(ctx) {
  const {app,db,requireAuth,permissions:p}=ctx;
  ctx.authenticateToken=token=>{
    if(!verifyCredential(ctx.config.secret,'api',token))return null;
    const row=db.prepare('SELECT * FROM api_tokens WHERE token_hash=? AND revoked_at IS NULL AND (expires_at IS NULL OR expires_at>?)').get(hashToken(token),ctx.now());
    if(!row)return null;
    const user=publicUser(db.prepare('SELECT * FROM users WHERE id=?').get(row.user_id));
    if(!user)return null;
    db.prepare('UPDATE api_tokens SET last_used_at=? WHERE id=?').run(ctx.now(),row.id);
    return {kind:'token',tokenId:row.id,user,scopes:JSON.parse(row.scopes_json)};
  };
  app.get('/api/v1/tokens',requireAuth,(req,res)=>{
    p.assertSelf(req);
    const state=req.query.state?choice(req.query.state,'state',['all','active','expired','revoked']):'all';
    const items=db.prepare('SELECT * FROM api_tokens WHERE user_id=? ORDER BY created_at DESC,id').all(req.user.id).map(publicToken).filter(token=>state==='all'||token.state===state);
    res.json(ctx.paginate(items,req.query));
  });
  app.post('/api/v1/tokens',requireAuth,(req,res)=>{
    p.assertSelf(req,req.user.id,'self:write');
    const input=tokenInput(req.body);
    if(req.auth.kind==='token'&&PERMISSIONS.some(permission=>scopeAllows(input.scopes,permission)&&!scopeAllows(req.auth.scopes,permission)))throw new AppError('FORBIDDEN','A token cannot grant scopes it does not hold',403,{scopes:'Requested scopes exceed the current token'});
    const id=ctx.id(),token=issueCredential(ctx.config.secret,'api'),time=ctx.now();
    const expiresAt=input.expiresInDays===null?null:new Date(Date.now()+input.expiresInDays*86400000).toISOString();
    db.prepare('INSERT INTO api_tokens(id,user_id,name,token_hash,scopes_json,created_at,expires_at) VALUES (?,?,?,?,?,?,?)').run(id,req.user.id,input.name,hashToken(token),JSON.stringify(input.scopes),time,expiresAt);
    const personalToken=publicToken(db.prepare('SELECT * FROM api_tokens WHERE id=?').get(id));
    securityEvent(ctx,req,'api_token',id,'created',{after:personalToken});
    res.status(201).json({personalToken,token});
  });
  app.delete('/api/v1/tokens/:tokenId',requireAuth,(req,res)=>{
    p.assertSelf(req,req.user.id,'self:write');
    const row=db.prepare('SELECT * FROM api_tokens WHERE id=? AND user_id=?').get(req.params.tokenId,req.user.id);
    if(!row)throw new AppError('NOT_FOUND','Personal token not found',404);
    if(row.revoked_at)throw new AppError('CONFLICT','Personal token is already revoked',409);
    db.prepare('UPDATE api_tokens SET revoked_at=? WHERE id=?').run(ctx.now(),row.id);
    const personalToken=publicToken(db.prepare('SELECT * FROM api_tokens WHERE id=?').get(row.id));
    securityEvent(ctx,req,'api_token',row.id,'revoked',{before:publicToken(row),after:personalToken});
    res.json({personalToken});
  });
}
